import {envelopeGainAt} from '../../dist/clip-envelope.js?v=2.2.84';
import {declickGain} from '../../dist/mobile-model.js?v=2.2.84';
// Frozen pre-optimization implementation, independent of the extracted helpers.
export function referenceGainAt(t,duration,volume=1,fadeIn=0,fadeOut=0,keyframes=[],gainEnvelope=[]){let keyed=1;const points=(keyframes||[]).filter(k=>Number.isFinite(+k.time)&&Number.isFinite(+k.value)).map(k=>({time:Math.max(0,+k.time),value:Math.max(0,Math.min(2,+k.value))})).sort((a,b)=>a.time-b.time);if(points.length){if(t<=points[0].time)keyed=points[0].value;else if(t>=points.at(-1).time)keyed=points.at(-1).value;else for(let i=1;i<points.length;i++)if(t<=points[i].time){const a=points[i-1],b=points[i],u=Math.max(0,Math.min(1,(t-a.time)/Math.max(1e-6,b.time-a.time)));keyed=a.value+(b.value-a.value)*u;break}}return Math.max(0,volume)*keyed*envelopeGainAt(t,gainEnvelope)*Math.max(0,Math.min(1,fadeIn?t/fadeIn:1,fadeOut?(duration-t)/fadeOut:1));}
export function referenceSchedule(graph,c,local,duration,trackVolume,playing){const now=this.context.currentTime,key=JSON.stringify([c.audio,trackVolume,duration]);if(!playing||graph.gainKey!==key||Math.abs(local-(graph.local+(now-graph.clock)))>.03||now>=graph.until-.04){const param=graph.output.gain;param.cancelScheduledValues(now);const span=playing?Math.min(.15,Math.max(.001,duration-local)):.001,count=Math.max(2,Math.ceil(span*48000)),curve=new Float32Array(count);for(let i=0;i<count;i++){const at=local+span*i/(count-1);curve[i]=trackVolume*referenceGainAt(at,duration,c.audio.volume,c.audio.fadeIn,c.audio.fadeOut,c.audio.gainKeyframes,c.audio.gainEnvelope)*declickGain(at,duration)}if(playing)param.setValueCurveAtTime(curve,now,span);else param.setValueAtTime(curve[0],now);graph.gainKey=key;graph.local=local;graph.clock=now;graph.until=now+span}}
